'use client'

import { useState } from 'react'
import { supabase } from '@/lib/supabase'
import { useLang } from '@/lib/LanguageContext'

type Produce = {
  id: string
  name: string
  variety?: string
  emoji?: string
  method?: string
  status: string
  price_tier_1_qty?: number
  price_tier_1_price?: number
  price_tier_2_qty?: number
  price_tier_2_price?: number
  price_tier_3_qty?: number
  price_tier_3_price?: number
  stock_qty?: number
  brix?: number
  pesticide_result?: string
  shelf_life_days?: number
  available_to?: string
}

type Farmer = {
  name?: string
  phone?: string
}

export default function ProduceTab({
  farmer,
  produce,
}: {
  farmer: Record<string, unknown>
  produce: Record<string, unknown>[]
}) {
  const { tx } = useLang()
  const f = farmer as Farmer
  const listings = produce as Produce[]
  const available = listings.filter((p) => p.status === 'available')
  const comingSoon = listings.filter((p) => p.status === 'coming_soon')

  const buildWhatsAppLink = (item: Produce) => {
    const message = tx.orderMessage
      .replace('{name}', f.name ?? '')
      .replace('{produce}', `${item.name}${item.variety ? ` (${item.variety})` : ''}`)
    return `https://wa.me/${f.phone?.replace(/\D/g, '')}?text=${encodeURIComponent(message)}`
  }

  return (
    <div className="space-y-6">
      {available.length > 0 && (
        <div>
          <div className="flex items-center gap-2 mb-3">
            <span className="bg-green-700 text-white text-xs font-bold px-3 py-1 rounded-full">
              {tx.availableNow}
            </span>
          </div>
          <div className="space-y-3">
            {available.map((item) => (
              <ProduceCard key={item.id} item={item} whatsappLink={buildWhatsAppLink(item)} />
            ))}
          </div>
        </div>
      )}

      {comingSoon.length > 0 && (
        <div>
          <div className="flex items-center gap-2 mb-3">
            <span className="bg-amber-100 text-amber-800 text-xs font-bold px-3 py-1 rounded-full">
              {tx.comingSoon}
            </span>
          </div>
          <div className="space-y-3">
            {comingSoon.map((item) => (
              <ComingSoonCard key={item.id} item={item} farmerId={item.id} />
            ))}
          </div>
        </div>
      )}

      {listings.length === 0 && (
        <div className="text-center py-10 text-gray-400 text-sm">{tx.noProduceListed}</div>
      )}
    </div>
  )
}

function ProduceCard({ item, whatsappLink }: { item: Produce; whatsappLink: string }) {
  const { tx } = useLang()
  const bgColors: Record<string, string> = {
    '🍅': 'bg-red-100', '🥬': 'bg-green-100', '🥭': 'bg-orange-100',
    '🍆': 'bg-purple-100', '🥕': 'bg-orange-100', '🌽': 'bg-yellow-100',
  }
  const emoji = item.emoji ?? '🌿'
  const bg = bgColors[emoji] ?? 'bg-green-100'

  return (
    <div className="bg-white rounded-xl border border-gray-100 overflow-hidden shadow-sm">
      <div className="flex gap-3 p-3">
        <div className={`${bg} rounded-xl w-14 h-14 flex items-center justify-center text-3xl flex-shrink-0`}>
          {emoji}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <div>
              <h3 className="font-bold text-gray-900 text-sm">{item.name}</h3>
              {item.variety && <p className="text-xs text-gray-500">{item.variety}</p>}
            </div>
            {item.stock_qty !== undefined && (
              <span className="text-xs text-gray-500 flex-shrink-0">{item.stock_qty} {tx.stockLeft}</span>
            )}
          </div>
          <div className="flex flex-wrap gap-1 mt-1.5">
            {item.method && (
              <span className="bg-green-100 text-green-800 text-[10px] font-semibold px-2 py-0.5 rounded-full">{item.method}</span>
            )}
            {item.pesticide_result && (
              <span className="bg-blue-100 text-blue-800 text-[10px] font-semibold px-2 py-0.5 rounded-full">{item.pesticide_result}</span>
            )}
            {item.brix && (
              <span className="bg-amber-100 text-amber-800 text-[10px] font-semibold px-2 py-0.5 rounded-full">BRIX {item.brix}</span>
            )}
          </div>
        </div>
      </div>

      {item.price_tier_1_price && (
        <div className="border-t border-gray-100 px-3 py-2 bg-gray-50">
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-gray-700">
            {item.price_tier_1_qty && item.price_tier_1_price && (
              <span>1–{item.price_tier_2_qty ? item.price_tier_2_qty - 1 : item.price_tier_1_qty} kg: <strong>₹{item.price_tier_1_price}</strong></span>
            )}
            {item.price_tier_2_qty && item.price_tier_2_price && (
              <span>{item.price_tier_2_qty}–{item.price_tier_3_qty ? item.price_tier_3_qty - 1 : '+'} kg: <strong>₹{item.price_tier_2_price}</strong></span>
            )}
            {item.price_tier_3_qty && item.price_tier_3_price && (
              <span>{item.price_tier_3_qty}+ kg: <strong>₹{item.price_tier_3_price}</strong></span>
            )}
          </div>
        </div>
      )}

      <div className="px-3 pb-3 pt-2">
        <a
          href={whatsappLink}
          target="_blank"
          rel="noopener noreferrer"
          className="block w-full text-center bg-green-700 text-white text-sm font-semibold py-2.5 rounded-lg"
        >
          {tx.orderWhatsApp}
        </a>
      </div>
    </div>
  )
}

function ComingSoonCard({ item, farmerId }: { item: Produce; farmerId: string }) {
  const { tx } = useLang()
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)

  const handleNotify = async () => {
    if (!name || !phone) return
    setLoading(true)
    await supabase.from('notify_requests').insert({
      farmer_id: farmerId,
      produce_name: item.name,
      requester_name: name,
      requester_phone: phone,
    })
    setSubmitted(true)
    setLoading(false)
  }

  return (
    <div className="bg-white rounded-xl border-2 border-dashed border-gray-200 p-4">
      <div className="flex items-center justify-between mb-2">
        <div>
          <h3 className="font-bold text-gray-700 text-sm">{item.emoji ?? '🌱'} {item.name}</h3>
          {item.available_to && (
            <p className="text-xs text-gray-500 mt-0.5">
              {tx.expected} {new Date(item.available_to).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}
            </p>
          )}
        </div>
        <span className="bg-amber-100 text-amber-700 text-[10px] font-bold px-2 py-1 rounded-full">
          {tx.comingSoon}
        </span>
      </div>

      {submitted ? (
        <p className="text-sm text-green-700 font-semibold text-center py-2">{tx.notifySuccess}</p>
      ) : (
        <div className="space-y-2 mt-3">
          <input type="text" placeholder={tx.yourName} value={name} onChange={(e) => setName(e.target.value)}
            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm" />
          <input type="tel" placeholder={tx.yourPhone} value={phone} onChange={(e) => setPhone(e.target.value)}
            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm" />
          <button onClick={handleNotify} disabled={loading}
            className="w-full bg-amber-600 text-white text-sm font-semibold py-2.5 rounded-lg disabled:opacity-60">
            {loading ? tx.saving : tx.notifyMe}
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import StoryTab from './tabs/StoryTab'
import ProduceTab from './tabs/ProduceTab'
import QualityTab from './tabs/QualityTab'
import ReviewsTab from './tabs/ReviewsTab'
import FarmMediaTab from './tabs/FarmMediaTab'

type Props = {
  farmer: Record<string, unknown>
  produce: Record<string, unknown>[]
  reviews: Record<string, unknown>[]
  media: Record<string, unknown>[]
}

export default function TabSection({ farmer, produce, reviews, media }: Props) {
  const { tx } = useLang()
  const [activeTab, setActiveTab] = useState(0)

  const TABS = [tx.story, tx.produce, tx.quality, tx.reviews, tx.farm]

  return (
    <div>
      <div className="sticky top-[53px] z-40 bg-white border-b border-gray-200">
        <div className="flex overflow-x-auto scrollbar-hide">
          {TABS.map((tab, i) => (
            <button
              key={tab}
              onClick={() => setActiveTab(i)}
              className={`flex-shrink-0 px-4 py-3 text-sm font-semibold border-b-2 transition-colors ${
                activeTab === i
                  ? 'border-green-700 text-green-700'
                  : 'border-transparent text-gray-500'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      <div className="px-4 py-4">
        {activeTab === 0 && <StoryTab farmer={farmer} />}
        {activeTab === 1 && <ProduceTab farmer={farmer} produce={produce} />}
        {activeTab === 2 && <QualityTab farmer={farmer} produce={produce} />}
        {activeTab === 3 && <ReviewsTab reviews={reviews} />}
        {activeTab === 4 && <FarmMediaTab media={media} />}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Farmer = {
  name: string
  village: string
  district: string
  state: string
  farming_since_year: number
}

export default function FarmCover({ farmer }: { farmer: Farmer }) {
  const { tx } = useLang()
  const [followed, setFollowed] = useState(false)

  useEffect(() => {
    const saved = localStorage.getItem(`follow_${farmer.name}`)
    if (saved) setFollowed(true)
  }, [farmer.name])

  const toggleFollow = () => {
    if (followed) {
      localStorage.removeItem(`follow_${farmer.name}`)
      setFollowed(false)
    } else {
      localStorage.setItem(`follow_${farmer.name}`, 'true')
      setFollowed(true)
    }
  }

  const initials = farmer.name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)

  return (
    <div className="relative">
      {/* SVG Farm Cover */}
      <div className="relative w-full h-44 bg-green-800 overflow-hidden">
        <svg viewBox="0 0 390 176" className="w-full h-full" preserveAspectRatio="xMidYMid slice">
          <rect width="390" height="176" fill="#1a4a1a" />
          <circle cx="320" cy="40" r="28" fill="#f9c74f" opacity="0.9" />
          <circle cx="320" cy="40" r="22" fill="#f9c74f" />
          {[0,45,90,135,180,225,270,315].map((angle, i) => (
            <line key={i}
              x1={320 + Math.cos((angle * Math.PI) / 180) * 26}
              y1={40 + Math.sin((angle * Math.PI) / 180) * 26}
              x2={320 + Math.cos((angle * Math.PI) / 180) * 36}
              y2={40 + Math.sin((angle * Math.PI) / 180) * 36}
              stroke="#f9c74f" strokeWidth="2.5"
            />
          ))}
          <rect x="0" y="130" width="390" height="46" fill="#2d5a1b" />
          <rect x="0" y="138" width="390" height="38" fill="#3a7a24" />
          <rect x="30" y="90" width="10" height="50" fill="#5c3d11" />
          <circle cx="35" cy="80" r="28" fill="#2d8a1f" />
          <circle cx="20" cy="90" r="18" fill="#33991f" />
          <circle cx="50" cy="88" r="20" fill="#267a18" />
          <rect x="340" y="95" width="10" height="45" fill="#5c3d11" />
          <circle cx="345" cy="82" r="26" fill="#2d8a1f" />
          <circle cx="330" cy="92" r="17" fill="#33991f" />
          <circle cx="358" cy="90" r="19" fill="#267a18" />
          {[0,1,2,3,4].map((i) => (
            <g key={i}>
              <line x1={120 + i * 32} y1="145" x2={120 + i * 32} y2="118" stroke="#4caf50" strokeWidth="2" />
              <ellipse cx={120 + i * 32} cy="116" rx="8" ry="12" fill="#66bb6a" />
              <ellipse cx={116 + i * 32} cy="122" rx="6" ry="9" fill="#81c784" />
              <ellipse cx={124 + i * 32} cy="121" rx="6" ry="9" fill="#81c784" />
            </g>
          ))}
          <rect x="165" y="110" width="60" height="35" fill="#8b6914" />
          <polygon points="155,112 195,88 235,112" fill="#a0522d" />
          <rect x="185" y="125" width="18" height="20" fill="#5c3d11" />
          <rect x="0" y="158" width="390" height="8" fill="#1565c0" opacity="0.6" />
          <rect x="0" y="159" width="390" height="4" fill="#42a5f5" opacity="0.4" />
        </svg>

        <div className="absolute top-3 left-3 bg-white/90 backdrop-blur-sm rounded-full px-3 py-1 text-xs font-semibold text-green-800">
          Natural farm · since {farmer.farming_since_year}
        </div>
      </div>

      {/* Identity section */}
      <div className="bg-white px-4 pt-4 pb-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="w-14 h-14 rounded-full bg-green-700 flex items-center justify-center text-white font-bold text-lg flex-shrink-0 -mt-8 border-3 border-white shadow-md">
              {initials}
            </div>
            <div>
              <h1 className="text-lg font-bold text-gray-900">{farmer.name}</h1>
              <p className="text-sm text-gray-500">
                {farmer.village}, {farmer.district}, {farmer.state}
              </p>
            </div>
          </div>

          <button
            onClick={toggleFollow}
            className={`flex-shrink-0 mt-1 px-4 py-1.5 rounded-full text-sm font-semibold border transition-all ${
              followed
                ? 'bg-green-700 text-white border-green-700'
                : 'bg-white text-green-700 border-green-700'
            }`}
          >
            {followed ? tx.following : tx.follow}
          </button>
        </div>
      </div>
    </div>
  )
}

